const ajv = new Ajv();
const schema = {
  type: 'object',
  properties: {ssn: {type: 'string'}},
  required: ['ssn'],
};

const validate = ajv.compile(schema);
const input = {ssn: 123456789};

if (!validate(input)) {
  console.log(JSON.stringify(validate.errors, null, 2));
} else {
  console.log('Valid');
}

