if (!validate(input)) {
  const errors = validate.errors ?? [];
  const message = errors
    .map((e: ErrorObject) => {
      const params = e.params as Record<string, unknown>;
      let field = 'input';

      // Use a typed cast for instancePath and avoid complex boolean chain for lint
      const path = (e as {instancePath?: string}).instancePath;
      if (path) {
        field = path.replace(/^\//, '');
      } else if (params?.missingProperty) {
        field = params.missingProperty as string;
      } else if (params?.propertyName) {
        field = params.propertyName as string;
      }

      if (e.keyword === 'required') {
        return `property ${field} is required`;
      }
      return `property ${field} ${e.message}`;
    })
    .join(', ');

